import React, { useState, useRef } from "react";
import "./App.css";

// --- Icons (SVG Components for portability) ---
const IconCopy = () => (
  <svg
    xmlns='http://www.w3.org/2000/svg'
    width='18'
    height='18'
    viewBox='0 0 24 24'
    fill='none'
    stroke='currentColor'
    strokeWidth='2'
    strokeLinecap='round'
    strokeLinejoin='round'
  >
    <rect x='9' y='9' width='13' height='13' rx='2' ry='2'></rect>
    <path d='M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1'></path>
  </svg>
);

const IconCheck = () => (
  <svg
    xmlns='http://www.w3.org/2000/svg'
    width='18'
    height='18'
    viewBox='0 0 24 24'
    fill='none'
    stroke='green'
    strokeWidth='3'
    strokeLinecap='round'
    strokeLinejoin='round'
  >
    <polyline points='20 6 9 17 4 12'></polyline>
  </svg>
);

const IconUpload = () => (
  <svg
    xmlns='http://www.w3.org/2000/svg'
    width='48'
    height='48'
    viewBox='0 0 24 24'
    fill='none'
    stroke='currentColor'
    strokeWidth='1'
    strokeLinecap='round'
    strokeLinejoin='round'
    className='text-blue-500 mb-4'
  >
    <path d='M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4'></path>
    <polyline points='17 8 12 3 7 8'></polyline>
    <line x1='12' y1='3' x2='12' y2='15'></line>
  </svg>
);

const IconSettings = () => (
  <svg
    xmlns='http://www.w3.org/2000/svg'
    width='20'
    height='20'
    viewBox='0 0 24 24'
    fill='none'
    stroke='currentColor'
    strokeWidth='2'
    strokeLinecap='round'
    strokeLinejoin='round'
  >
    <circle cx='12' cy='12' r='3'></circle>
    <path d='M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z'></path>
  </svg>
);

// --- Components ---

const CopyInput = ({ label, value }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className='flex flex-col gap-1 w-full'>
      <label className='text-xs font-semibold text-gray-500 uppercase tracking-wider'>{label}</label>
      <div className='flex items-center gap-2 bg-white border border-gray-200 rounded-lg p-2 shadow-sm hover:border-blue-400 transition-colors'>
        <code className='flex-1 text-sm text-gray-800 truncate font-mono'>{value || "Waiting for file..."}</code>
        <button
          onClick={handleCopy}
          disabled={!value}
          className='p-2 rounded-md hover:bg-gray-100 text-gray-500 transition-all active:scale-95 disabled:opacity-50'
          title='Copy to clipboard'
        >
          {copied ? <IconCheck /> : <IconCopy />}
        </button>
      </div>
    </div>
  );
};

function App() {
  // State
  const [fileData, setFileData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [fileName, setFileName] = useState("");

  // Specific requirements: Device ID & Hash
  const [deviceId, setDeviceId] = useState("");
  const [deviceHash, setDeviceHash] = useState("");

  // Settings
  const [separator, setSeparator] = useState(",");
  const [hasHeaders, setHasHeaders] = useState(true);
  const [showAdvanced, setShowAdvanced] = useState(false);

  const fileInputRef = useRef(null);

  // Helper: Calculate SHA-256 Hash
  const calculateHash = async text => {
    const encoder = new TextEncoder();
    const data = encoder.encode(text);
    const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
  };

  // Helper: Generate Mock Device ID (UUID)
  const generateDeviceId = () => {
    return "dev_" + crypto.randomUUID().split("-").join("").substring(0, 16);
  };

  // Handle File Processing
  const processFile = async file => {
    if (!file) return;

    setFileName(file.name);

    // 1. Generate ID and Hash immediately
    const text = await file.text();
    const hash = await calculateHash(text);
    const newId = generateDeviceId();

    setDeviceHash(hash);
    setDeviceId(newId);

    // 2. Parse CSV
    // Simple parser logic (split by newlines, then by separator)
    // Note: A library like 'papaparse' is better for production, but this works for simple copy-paste.
    const rows = text.split(/\r?\n/).filter(row => row.trim() !== "");

    if (rows.length === 0) return;

    let parsedData = rows.map(row => row.split(separator));

    if (hasHeaders) {
      setHeaders(parsedData[0]);
      setFileData(parsedData.slice(1));
    } else {
      // Generate Generic Headers (Col 1, Col 2...)
      const maxCols = Math.max(...parsedData.map(row => row.length));
      setHeaders(Array.from({ length: maxCols }, (_, i) => `Column ${i + 1}`));
      setFileData(parsedData);
    }
  };

  const handleFileChange = e => {
    processFile(e.target.files[0]);
  };

  // UI Handlers
  const triggerFileInput = () => fileInputRef.current.click();

  return (
    <div className='min-h-screen bg-slate-50 text-slate-800 font-sans selection:bg-blue-100'>
      {/* Navigation */}
      <nav className='bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between sticky top-0 z-50 shadow-sm'>
        <div className='flex items-center gap-2'>
          <div className='w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold text-lg'>C</div>
          <span className='text-xl font-bold tracking-tight text-slate-900'>
            Project CSV <span className='text-xs font-normal text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full ml-2'>Clone</span>
          </span>
        </div>
        <div className='hidden md:flex gap-6 text-sm font-medium text-gray-600'>
          <a href='#' className='hover:text-blue-600 transition-colors'>
            Home
          </a>
          <a href='#' className='hover:text-blue-600 transition-colors'>
            GitHub
          </a>
          <a href='#' className='hover:text-blue-600 transition-colors'>
            About
          </a>
          <a href='#' className='hover:text-blue-600 transition-colors'>
            Contact
          </a>
        </div>
      </nav>

      <main className='max-w-7xl mx-auto px-4 py-8 space-y-8'>
        {/* Settings Section */}
        <section className='bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden'>
          <div
            className='px-6 py-4 bg-gray-50 border-b border-gray-200 flex justify-between items-center cursor-pointer hover:bg-gray-100 transition-colors'
            onClick={() => setShowAdvanced(!showAdvanced)}
          >
            <div className='flex items-center gap-2'>
              <IconSettings />
              <h2 className='font-semibold text-gray-700'>CSV Configuration</h2>
            </div>
            <span className={`transform transition-transform ${showAdvanced ? "rotate-180" : ""}`}>▼</span>
          </div>

          {/* Configuration Controls */}
          <div className={`p-6 grid gap-6 md:grid-cols-2 lg:grid-cols-3 transition-all ${showAdvanced ? "block" : "hidden md:grid"}`}>
            {/* Control 1: Separator */}
            <div>
              <label className='block text-sm font-medium text-gray-700 mb-2'>Column Separator</label>
              <select
                value={separator}
                onChange={e => setSeparator(e.target.value)}
                className='w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 bg-white py-2 px-3 border'
              >
                <option value=','>Comma (,)</option>
                <option value=';'>Semi-colon (;)</option>
                <option value='|'>Bar (|)</option>
                <option value='\t'>Tab</option>
              </select>
            </div>

            {/* Control 2: Headers */}
            <div className='flex items-center'>
              <label className='flex items-center gap-3 cursor-pointer'>
                <input
                  type='checkbox'
                  checked={hasHeaders}
                  onChange={e => setHasHeaders(e.target.checked)}
                  className='w-5 h-5 text-blue-600 rounded border-gray-300 focus:ring-blue-500'
                />
                <span className='text-sm font-medium text-gray-700'>First row contains headers</span>
              </label>
            </div>

            {/* Control 3: Action */}
            <div className='flex items-end'>
              <button onClick={() => setFileData([])} className='text-sm text-red-500 hover:text-red-700 font-medium underline'>
                Reset All Settings
              </button>
            </div>
          </div>
        </section>

        {/* --- REQUIRED: Device ID & Hash Output Section --- */}
        {fileName && (
          <section className='bg-gradient-to-r from-slate-800 to-slate-900 rounded-xl shadow-lg p-6 text-white transform transition-all animate-in fade-in slide-in-from-bottom-4'>
            <div className='flex items-center justify-between mb-4 border-b border-slate-700 pb-2'>
              <h3 className='text-lg font-bold flex items-center gap-2'>
                <span className='w-2 h-2 bg-green-400 rounded-full animate-pulse'></span>
                Device Identity Generated
              </h3>
              <span className='text-xs text-slate-400 font-mono'>{fileName}</span>
            </div>

            <div className='grid md:grid-cols-2 gap-6'>
              {/* Custom Component for Device ID */}
              <CopyInput label='Device ID' value={deviceId} />
              {/* Custom Component for Device Hash */}
              <CopyInput label='Device Hash (SHA-256)' value={deviceHash} />
            </div>
          </section>
        )}

        {/* File Upload Area */}
        {!fileName && (
          <div
            onClick={triggerFileInput}
            className='border-2 border-dashed border-gray-300 rounded-xl p-12 flex flex-col items-center justify-center text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-all group'
          >
            <input type='file' accept='.csv,.txt' onChange={handleFileChange} className='hidden' ref={fileInputRef} />
            <div className='p-4 bg-gray-100 rounded-full group-hover:bg-blue-100 transition-colors mb-4'>
              <IconUpload />
            </div>
            <h3 className='text-lg font-semibold text-gray-700 group-hover:text-blue-600'>Select or Drop .csv files</h3>
            <p className='text-gray-500 mt-2 text-sm'>Process locally. No data is sent to server.</p>
          </div>
        )}

        {/* Data Table Viewer */}
        {fileData.length > 0 && (
          <div className='bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden'>
            <div className='px-6 py-4 border-b border-gray-200 flex justify-between items-center bg-gray-50'>
              <h3 className='font-semibold text-gray-700'>File Preview</h3>
              <span className='text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded-md font-medium'>{fileData.length} Rows</span>
            </div>
            <div className='overflow-x-auto'>
              <table className='w-full text-left text-sm whitespace-nowrap'>
                <thead className='bg-gray-50 text-gray-500 font-medium border-b border-gray-200'>
                  <tr>
                    <th className='px-6 py-3 w-16 text-center'>#</th>
                    {headers.map((header, index) => (
                      <th key={index} className='px-6 py-3'>
                        {header}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className='divide-y divide-gray-100'>
                  {fileData.map((row, rowIndex) => (
                    <tr key={rowIndex} className='hover:bg-blue-50/50 transition-colors group'>
                      <td className='px-6 py-3 text-center text-gray-400 bg-gray-50/50 font-mono text-xs'>{rowIndex + 1}</td>
                      {row.map((cell, cellIndex) => (
                        <td key={cellIndex} className='px-6 py-3 text-gray-700'>
                          {/* Basic inline editing mockup */}
                          <input defaultValue={cell} className='bg-transparent border-none p-0 w-full focus:ring-0 text-gray-700 cursor-text' />
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className='max-w-7xl mx-auto px-4 py-8 text-center text-gray-400 text-sm'>
        <p>&copy; 2026 Project CSV Clone. Open Source & Local Processing.</p>
      </footer>
    </div>
  );
}

export default App;
